diff --git a/tests/terraform/checks/resource/kubernetes/test_CPULimits.py b/tests/terraform/checks/resource/kubernetes/test_CPULimits.py
new file mode 100644
index 000000000..7ea2d9b3c
--- /dev/null
+++ b/tests/terraform/checks/resource/kubernetes/test_CPULimits.py
@@ -0,0 +1,44 @@
+import unittest
+from pathlib import Path
+
+from checkov.runner_filter import RunnerFilter
+from checkov.terraform.checks.resource.kubernetes.CPULimits import check
+from checkov.terraform.runner import Runner
+
+
+class TestCPULimits(unittest.TestCase):
+    def test(self):
+        # given
+        test_files_dir = Path(__file__).parent / "example_CPULimits"
+
+        # when
+        report = Runner().run(root_folder=str(test_files_dir), runner_filter=RunnerFilter(checks=[check.id]))
+
+        # then
+        summary = report.get_summary()
+
+        passing_resources = {
+            "kubernetes_pod.pass",
+        }
+
+        failing_resources = {
+            "kubernetes_pod.fail",
+            "kubernetes_pod.fail2",
+            "kubernetes_pod.fail3",
+            "kubernetes_pod.fail4",
+        }
+
+        passed_check_resources = {c.resource for c in report.passed_checks}
+        failed_check_resources = {c.resource for c in report.failed_checks}
+
+        self.assertEqual(summary["passed"], 1)
+        self.assertEqual(summary["failed"], 4)
+        self.assertEqual(summary["skipped"], 0)
+        self.assertEqual(summary["parsing_errors"], 0)
+
+        self.assertEqual(passing_resources, passed_check_resources)
+        self.assertEqual(failing_resources, failed_check_resources)
+
+
+if __name__ == '__main__':
+    unittest.main()

